_deleteCompleted() {
  if (this.dbView) {
    this.dbView.onDeleteCompleted(true);
  }
  this.listener.onMessagesRemoved();
},

/**
 * See _deleteCompleted for an explanation of what is going on.
 */
_deleteFailed() {
  if (this.dbView) {
    this.dbView.onDeleteCompleted(false);
  }
  this.listener.onMessageRemovalFailed();
},
